from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from djmoney.money import Money
from .models import DepartmentBudgetEntry

@api_view(['PATCH'])
@permission_classes([IsAuthenticated])
def update_budget_allocation(request, entry_id):
    new_allocation = request.data.get('allocation')
    currency = request.data.get('currency', 'USD')

    # Restrict modification to budget entries managed by the authenticated user
    entry = DepartmentBudgetEntry.objects.filter(
        id=entry_id,
        department__manager=request.user,
        allocated_amount_currency=currency
    ).first()
    if not entry:
        return Response({"error": "Budget entry not found"}, status=status.HTTP_404_NOT_FOUND)

    entry.allocated_amount = Money(new_allocation, currency)
    entry.save(update_fields=['allocated_amount'])
    return Response({"entry_id": entry.id, "allocated_amount": str(entry.allocated_amount)})
